print({"unique_friend_email_count": len(friend_emails)})

candidate_received_transactions_by_id = {}
transaction_pages_by_friend = {}
transaction_page_limit = 20
for friend_email in friend_emails:
    transaction_page_index = 0
    transaction_pages_by_friend[friend_email] = 0
    while True:
        transaction_page = apis.venmo.show_transactions(
            access_token=venmo_access_token,
            user_email=friend_email,
            direction="received",
            min_created_at=min_created_at,
            max_created_at=max_created_at,
            page_index=transaction_page_index,
            page_limit=transaction_page_limit,
        )
        transaction_pages_by_friend[friend_email] += 1
        for transaction in transaction_page:
            candidate_received_transactions_by_id[transaction["transaction_id"]] = transaction
        if len(transaction_page) < transaction_page_limit:
            break
        transaction_page_index += 1
print({
    "friends_queried": len(friend_emails),
    "transaction_pages_read": sum(transaction_pages_by_friend.values()),
    "candidate_transaction_count": len(candidate_received_transactions_by_id),
